from datetime import date, timedelta
from typing import Dict, Set, Tuple


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days: int = loan_days
        self.daily_fine: float = daily_fine
        self.catalog: Set[str] = set()
        # Maps book_id -> (borrower_username, borrow_date)
        self.active_loans: Dict[str, Tuple[str, date]] = {}
        # Maps user -> set of book_ids currently borrowed
        self.user_loans: Dict[str, Set[str]] = {}
        # Maps user -> total unpaid fine amount
        self.fines: Dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        """Add a new book to the library catalog."""
        self.catalog.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        """Borrow a book for a user on a given date."""
        if book_id not in self.catalog:
            raise ValueError(f"Book '{book_id}' is not in the library catalog.")

        if book_id in self.active_loans:
            raise ValueError(f"Book '{book_id}' is currently borrowed.")

        current_loans = self.user_loans.get(user, set())
        # A user with unpaid fines may hold at most one book at a time
        if self.unpaid_fines(user) > 0 and len(current_loans) >= 1:
            raise ValueError(
                f"User '{user}' has unpaid fines and cannot borrow more than one book."
            )

        self.active_loans[book_id] = (user, day)
        if user not in self.user_loans:
            self.user_loans[user] = set()
        self.user_loans[user].add(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        if book_id not in self.active_loans:
            raise ValueError(f"Book '{book_id}' is not currently borrowed.")

        borrower, borrow_date = self.active_loans[book_id]
        if borrower != user:
            raise ValueError(f"Book '{book_id}' was not borrowed by '{user}'.")

        # Clean up loan records
        del self.active_loans[book_id]
        self.user_loans[user].remove(book_id)

        due_date = borrow_date + timedelta(days=self.loan_days)
        delay_days = 0

        # Calculate overdue days excluding weekends (Saturday: 5, Sunday: 6)
        if day > due_date:
            curr = due_date + timedelta(days=1)
            while curr <= day:
                if curr.weekday() < 5:  # Monday to Friday
                    delay_days += 1
                curr += timedelta(days=1)

        fine = delay_days * self.daily_fine
        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        """Return the current amount of unpaid fines for the user."""
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.fines[user] = 0.0
```

